  // your code here
}

test_suite:
test('clones primitives', () => {
  expect(structuredClonePolyfill(42)).toBe(42);
  expect(structuredClonePolyfill('hi')).toBe('hi');
  expect(structuredClonePolyfill(null)).toBe(null);
});

test('deep clones arrays', () => {
  const arr = [1, [2, 3]];
  const clone = structuredClonePolyfill(arr);
  clone[1].push(4);
  expect(arr[1]).toEqual([2, 3]);
});

test('deep clones objects', () => {
  const obj = { a: { b: 1 } };
  const clone = structuredClonePolyfill(obj);
  clone.a.b = 99;
  expect(obj.a.b).toBe(1);
});

test('clones Date objects', () => {
  const d = new Date('2024-06-01');
  const clone = structuredClonePolyfill(d);
  expect(clone).toEqual(d);
  expect(clone).not.toBe(d);
});

// __hidden__
test('nested mix of arrays, objects, and Date', () => {
  const val = { list: [new Date('2020-01-01'), { x: 1 }] };
  const clone = structuredClonePolyfill(val);
  clone.list[1].x = 99;
  expect(val.list[1].x).toBe(1);
  expect(clone.list[0]).toEqual(val.list[0]);
  expect(clone.list[0]).not.toBe(val.list[0]);
});

solution:
export function structuredClonePolyfill(value) {
  if (value === null || typeof value !== 'object') return value;
  if (value instanceof Date) return new Date(value.getTime());
  if (Array.isArray(value)) return value.map(structuredClonePolyfill);
  return Object.fromEntries(
    Object.entries(value).map(([k, v]) => [k, structuredClonePolyfill(v)])
  );
}
